// ============================================================
// BOOTSTRAP CONFIG
// Ganti SHEET_ID ke Sheet ID spreadsheet "Persada_Cisoka_Database".
// ============================================================
const SHEET_ID = '1dJWq7iq5PRGRguW6GRAgtclgvhSqppa-D6tSNrAo1PU';   // <-- EDIT INI
const wh = $input.first() ? $input.first().json : {};
return [{ json: { ...wh, sheet_id: SHEET_ID } }];

// ============================================================
// PARSE CONFIG (ENGINE) — baca tab CONFIG (key|value) jadi objek config.
// Nilai list/JSON ditulis sbg JSON string di sel value.
// Perubahan 2026-07-17: default bot_name 'VIRA' -> 'Vira'.
// ============================================================
const rows = $('Read CONFIG').all().map(i => i.json);
const sheetId = $('Bootstrap Config').first().json.sheet_id || '';
const raw = {};
for (const r of rows) {
  const k = String(r.key ?? r.Key ?? r.KEY ?? '').trim();
  if (!k) continue;
  raw[k] = (r.value ?? r.Value ?? r.VALUE ?? '');
}
const str = (k, def='') => { const v = raw[k]; return (v===undefined||v===null||String(v).trim()==='') ? def : String(v).trim(); };
const num = (k, def) => { const s = str(k,''); if (s==='') return def; const n = Number(s); return Number.isFinite(n)?n:def; };
const bool = (k, def=false) => { const v = str(k,'').toLowerCase(); if (v==='') return def; return ['true','yes','y','on','1','aktif','ya'].includes(v); };
const jsonArr = (k) => { try { const v = str(k,''); if (!v) return []; const p = JSON.parse(v); return Array.isArray(p) ? p : []; } catch(e){ return []; } };

const config = {
  sheet_id: sheetId,
  client_name: str('client_name', 'Persada Cisoka Residence'),
  bot_name: str('bot_name', 'Vira'),
  bot_language: str('bot_language', 'id'),
  system_prompt: str('system_prompt', ''),
  admin_phone: str('admin_phone', ''),
  admin_phone_display: str('admin_phone_display', ''),
  field_team_phone: (() => {
    const a = jsonArr('field_team_phone');
    if (a.length) return a.map(x => String(x).replace(/\D/g,'')).filter(Boolean);
    const s = str('field_team_phone','');
    return s ? [s.replace(/\D/g,'')].filter(Boolean) : [];
  })(),
  media_team_phone: (() => {
    const a = jsonArr('media_team_phone');
    if (a.length) return a.map(x => String(x).replace(/\D/g,'')).filter(Boolean);
    const s = str('media_team_phone','');
    return s ? [s.replace(/\D/g,'')].filter(Boolean) : [];
  })(),
  brochure_url: str('brochure_url', ''),
  media_catalog: jsonArr('media_catalog'),
  survey_slots: jsonArr('survey_slots'),
  survey_open_hour: num('survey_open_hour', 8),
  survey_close_hour: num('survey_close_hour', 17),
  followup_max: num('followup_max', 3),
  followup_interval_hours: num('followup_interval_hours', 24),
  followup_open_hour: num('followup_open_hour', 9),
  followup_close_hour: num('followup_close_hour', 18),
  followup_templates: jsonArr('followup_templates'),
  lead_source_map: jsonArr('lead_source_map'),
  whitelist_enabled: bool('whitelist_enabled', false),
  whitelist_numbers: jsonArr('whitelist_numbers').map(x => String(x).replace(/\D/g,'')),
  rate_limit_max: num('rate_limit_max', 5),
  rate_limit_window_sec: num('rate_limit_window_sec', 60),
  debounce_seconds: num('debounce_seconds', 60),
  // Kredensial Kirimi utk endpoint multipart send-message-file (upload binary).
  // Custom-auth n8n TIDAK reliabel meng-inject body ke multipart/form-data,
  // jadi user_code/secret/device_id di-supply sbg field form via CONFIG sheet.
  // Node teks (JSON body) tetap pakai credential httpCustomAuth.
  // ---- [V2.1 VISION] toggle add-on & batas biaya (semua opsional di sheet CONFIG) ----
  // vision_mode:
  //   'off'  = perilaku V1.3 - media tanpa teks di-drop, Vira diam.
  //   'ack'  = media DIAKUI sopan tapi TIDAK dikirim ke Claude. NOL biaya.
  //            <- pakai ini selama add-on vision belum disetujui klien.
  //   'full' = vision aktif penuh (add-on berbayar, ~Rp 40 / chat bergambar).
  // Kalau key 'vision_mode' tidak ada di sheet, jatuh ke key lama 'vision_enabled'
  // supaya sheet yang belum diupdate tetap jalan.
  vision_mode: (() => {
    const m = str('vision_mode', '').toLowerCase();
    if (['off', 'ack', 'full'].includes(m)) return m;
    return bool('vision_enabled', true) ? 'full' : 'ack';
  })(),
  vision_enabled: bool('vision_enabled', true),
  vision_max_images: num('vision_max_images', 3),
  vision_model: str('vision_model', 'claude-haiku-4-5'),
  vision_max_tokens: num('vision_max_tokens', 1000),
  kirimi_user_code: str('kirimi_user_code', ''),
  kirimi_secret: str('kirimi_secret', ''),
  kirimi_device_id: str('kirimi_device_id', ''),
};
const passthrough = $('Bootstrap Config').first() ? $('Bootstrap Config').first().json : {};
return [{ json: { ...passthrough, config } }];

// Blocklist Gate — VIRA Steven
// Menggantikan Whitelist Gate milik Persada. Bot ini publik, jadi default-nya
// semua orang boleh masuk; yang disaring hanya nomor di blocklist dan nomor bot sendiri.
const cfg = $('Parse Config').first().json.config || {};
const item = $input.first().json;

const digits = (s) => String(s || '').replace(/\D/g, '');
const from = digits(item.from || item.no_wa || '');
const lid  = digits(item.originLid || item.lid || '');

// 1) jangan pernah membalas diri sendiri (bisa memicu loop tak berujung)
const ignoreSelf = String(cfg.ignore_self_number ?? 'true').toLowerCase() === 'true';
const botNumber = digits(cfg.bot_wa_number || '');
if (ignoreSelf && botNumber && (from === botNumber || lid === botNumber)) {
  return [];
}

// 2) blocklist manual dari CONFIG
let blocked = [];
try {
  const rawList = cfg.blocklist_numbers;
  blocked = Array.isArray(rawList) ? rawList : JSON.parse(rawList || '[]');
} catch (e) {
  blocked = [];   // CONFIG salah format -> jangan sampai memblokir semua orang
}
const blockedDigits = blocked.map(digits).filter(Boolean);
if (blockedDigits.length && (blockedDigits.includes(from) || blockedDigits.includes(lid))) {
  return [];
}

return $input.all();

// NODE: Chat Counter
// ====================================================================
// [V2 - VISION] Gerbang masuk & parsing payload Kirimi.
// V1.3: SEMUA messageType != "text" di-DROP di sini (return []).
// V2  : - gambar (dengan / tanpa caption) DITERUSKAN, media_url dibawa
//         ke MSG_BUFFER supaya ikut logika debounce & gabung pesan.
//       - media non-gambar (video/suara/dokumen/lokasi) diteruskan
//         sebagai PENANDA saja (tidak dikirim ke Vision) supaya Vira
//         bisa menjawab sopan, bukan diam.
// ====================================================================
const webhookData = $input.first();
const body = webhookData.json.body || {};

// Ambil data dari Kirimi
const userMessage = body.message || "";
const messageType = String(body.messageType || "").trim().toLowerCase();
const userNumber = body.from || "unknown";  // TIDAK strip @lid, passthrough as-is
const _isLid    = String(userNumber).toLowerCase().includes('@lid');
const userLid   = String(body.originLid || (_isLid ? userNumber : '')).replace(/\D/g, '');
const userPhone = _isLid ? '' : String(userNumber).replace(/\D/g, '');
const userName = body.name || body.pushName || body.notifyName || "User";
const isFromMe = body.isFromMe === true;
const eventType = body.event || "";

// -- [V2] Deteksi media masuk ------------------------------------------------
// Nama field URL bisa beda antar versi gateway -> cek beberapa kandidat.
const mediaUrl = String(
  body.mediaUrl ?? body.media_url ?? body.fileUrl ?? body.file_url ?? body.url ?? ''
).trim();
const mediaMime = String(
  body.mimetype ?? body.mimeType ?? body.mime_type ?? ''
).trim().toLowerCase();

const IMAGE_TYPES = ['image','imagemessage','photo','gambar'];
// [V2.1] Stiker dipindah ke media non-gambar: TIDAK dikirim ke Vision (nol biaya).
// Di chat WA Indonesia stiker dipakai sbg basa-basi, frekuensinya bisa > foto asli.
const OTHER_MEDIA_TYPES = ['video','videomessage','audio','audiomessage','ptt','voice',
  'document','documentmessage','file','location','locationmessage','contact','vcard',
  'sticker','stickermessage'];
// [V2.1] Tipe sistem: TIDAK PERNAH memicu balasan, walaupun membawa teks.
// V2.0 memakai blacklist implisit (lolos asal body.message tidak kosong), sehingga
// reaction beremoji ikut diproses jadi 1 eksekusi penuh + Vira membalasnya.
const DROP_TYPES = ['reaction','reactionmessage','protocol','protocolmessage',
  'status','statusmessage','revoked','revoke','poll_update','pollupdate',
  'e2e_notification','notification','call','call_log','ciphertext'];

const looksImage      = IMAGE_TYPES.includes(messageType) || mediaMime.startsWith('image/');
const looksOtherMedia = OTHER_MEDIA_TYPES.includes(messageType);
const hasText         = !!userMessage && String(userMessage).trim() !== '';

// media_kind: 'none' | 'image' (bisa dibaca Vision) | 'other' (cuma penanda)
let mediaKind = 'none';
if (looksImage && mediaUrl) mediaKind = 'image';
else if (looksImage || looksOtherMedia) mediaKind = 'other';
else if (mediaUrl && messageType !== 'text' && messageType !== 'chat') mediaKind = 'other';

const MEDIA_LABEL = {
  video:'video', videomessage:'video',
  audio:'pesan suara', audiomessage:'pesan suara', ptt:'pesan suara', voice:'pesan suara',
  document:'dokumen', documentmessage:'dokumen', file:'dokumen',
  location:'lokasi', locationmessage:'lokasi', contact:'kontak', vcard:'kontak',
  sticker:'stiker', stickermessage:'stiker'
};
const mediaLabel = mediaKind === 'image'
  ? 'gambar'
  : (mediaKind === 'other' ? (MEDIA_LABEL[messageType] || 'lampiran') : '');

// [V2.1] Gerbang 1 - tipe sistem/reaction selalu dibuang, walau membawa teks.
if (DROP_TYPES.includes(messageType)) {
    console.log('STOP: tipe sistem/reaction, tidak diproses. type=' + messageType);
    return [];
}

// [V2.1] Gerbang 2 - mode add-on. vision_mode=off => perilaku V1.3 (media di-drop).
// Chat Counter berada SESUDAH Parse Config di rantai (Parse Config -> Whitelist Gate
// -> Chat Counter), jadi referensi ini valid.
const cfgCC = (() => { try { return $('Parse Config').first().json.config || {}; } catch (e) { return {}; } })();
const visionModeCC = String(cfgCC.vision_mode || 'full').toLowerCase();
// Setara V1.3 PERSIS: V1.3 membuang semua messageType != 'text', termasuk gambar
// yang ADA captionnya. Jadi di mode 'off' media di-drop tanpa melihat ada teks/tidak.
if (visionModeCC === 'off' && mediaKind !== 'none') {
    console.log('STOP: vision_mode=off, semua media di-drop (perilaku V1.3). type=' + messageType);
    return [];
}

// Filter: buang yang BUKAN teks DAN BUKAN media (status, event sistem)
if (mediaKind === 'none' && !hasText) {
    console.log('STOP: bukan pesan teks valid & tidak ada media. type=' + messageType);
    return [];
}

console.log('LANJUT: type=' + (messageType || '(kosong)') + ' | media=' + mediaKind + ' | text=' + hasText);
console.log('No WA:', userNumber);

// Counter sederhana
let counter = $vars.chatCounter || 0;
counter++;
$vars.chatCounter = counter;

// Format tanggal & jam WIB
const now = new Date();
const formattedDate = now.toLocaleDateString('en-GB', {
    timeZone: 'Asia/Jakarta',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
});
const formattedTime = now.toLocaleTimeString('id-ID', {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
    timeZone: 'Asia/Jakarta'
}).replace(/\./g, ':');

const processStartTs = Date.now();

// [V2] Label utk kolom STATS ("Pesan Pertama"). JANGAN dipakai sebagai
// user_message/prompt -- kata "gambar"/"foto" akan memicu regex wantsMedia
// di Preprocess dan bikin Vira salah kirim brosur.
const statsMessage = hasText ? userMessage : (mediaKind !== 'none' ? ('[' + mediaLabel + ']') : '');

const aiInputText = `[SYSTEM_DATA]
CHAT_COUNTER: ${counter}
USER_NAME: ${userName}
USER_MESSAGE: "${userMessage}"

[USER QUERY]
${userMessage}`;

return [{
    json: {
        chat_counter: counter,
        user_wa: userNumber,
        user_lid: userLid,
        user_phone: userPhone,
        user_name: userName,
        formatted_date: formattedDate,
        formatted_time: formattedTime,
        ai_input_text: aiInputText,
        original_message: userMessage,
        body: body,
        message_type: messageType,
        process_start_ts: processStartTs,
        // ---- [V2 VISION] ----
        media_url: mediaUrl,
        media_kind: mediaKind,
        media_mime: mediaMime,
        media_label: mediaLabel,
        has_media: mediaKind !== 'none',
        stats_message: statsMessage
    }
}];

// ====================================================================
// RESOLVE USER ROW (fondasi identitas)
// No WA = kunci PRIMER, lid = backup. TIDAK PERNAH fallback rows[0].
// ====================================================================
const cc = $('Chat Counter').first().json;
const digits = v => String(v ?? '').replace(/\D/g, '');
const phone = digits(cc.user_phone);
const lid = digits(cc.user_lid);

if (!phone && !lid) {
  throw new Error('Identitas user kosong (phone & lid tidak ada) - payload webhook tidak dikenal: ' + JSON.stringify(cc.body?.from ?? null));
}

let rows = [];
try {
  rows = $('Read User STATS').all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
} catch (e) { console.warn('Read User STATS tidak terbaca:', e.message); }

let row = null;
if (phone) row = rows.find(r => digits(r['No WA']) === phone) || null;
if (!row && lid) {
  row = rows.find(r => digits(r['lid']) === lid) || rows.find(r => digits(r['No WA']) === lid) || null;
}

const resolvedKey = row ? String(row['No WA']).trim() : (phone || lid);
const greetingSent = row ? String(row['greeting_sent'] || '').trim().toUpperCase() : '';
console.log('resolved_key=' + resolvedKey + ' | row_found=' + (!!row));

return [{
  json: {
    ...cc,
    resolved_key: resolvedKey,
    row_found: !!row,
    bot_mode: row ? String(row['bot_mode'] || '').trim().toUpperCase() : '',
    greeting_sent: greetingSent,
    is_new_user: !row || greetingSent !== 'Y',
    buffer_done_ts: Number(row ? (row['buffer_done_ts'] || 0) : 0) || 0,
    unit_interest: row ? String(row['unit_interest'] || '').trim() : '',
    unit_interest_ts: Number(row ? (row['unit_interest_ts'] || 0) : 0) || 0,
    budget_range: row ? String(row['budget_range'] || '').trim() : '',
    budget_range_ts: Number(row ? (row['budget_range_ts'] || 0) : 0) || 0,
    nama_lengkap: row ? String(row['nama_lengkap'] || '').trim() : '',
    nama_lengkap_ts: Number(row ? (row['nama_lengkap_ts'] || 0) : 0) || 0,
    lokasi_kerja: row ? String(row['lokasi_kerja'] || '').trim() : '',
lokasi_kerja_ts: Number(row ? (row['lokasi_kerja_ts'] || 0) : 0) || 0,
    pending_survey_tanggal: row ? String(row['pending_survey_tanggal'] || '').trim() : '',
    pending_survey_jam: row ? String(row['pending_survey_jam'] || '').trim() : '',
    pending_survey_unit: row ? String(row['pending_survey_unit'] || '').trim() : '',
    pending_survey_ts: Number(row ? (row['pending_survey_ts'] || 0) : 0) || 0,
    lead_source_db: row ? String(row['lead_source'] || '').trim() : '',
    userRow: row ? { ...row } : {},
    nama_bisnis: row ? String(row['nama_bisnis'] || '').trim() : '',
    industri: row ? String(row['industri'] || '').trim() : '',
    masalah_utama: row ? String(row['masalah_utama'] || '').trim() : '',
    masalah_utama_ts: Number(row ? (row['masalah_utama_ts'] || 0) : 0) || 0,
    volume_chat: row ? String(row['volume_chat'] || '').trim() : '',
    volume_chat_ts: Number(row ? (row['volume_chat_ts'] || 0) : 0) || 0,
    minat_paket: row ? String(row['minat_paket'] || '').trim() : '',
    minat_paket_ts: Number(row ? (row['minat_paket_ts'] || 0) : 0) || 0,
    deck_requested: row ? String(row['deck_requested'] || '').trim() : '',
    brief_terisi: row ? String(row['brief_terisi'] || '').trim() : '',
    bahasa: row ? String(row['bahasa'] || '').trim() : '',
    counter_db: Number(row ? (row['Counter'] || 0) : 0) || 0
  }
}];

// Rate Limiter: cegah spam (maks 5 pesan per menit per user)
const input = $input.first().json;
const userWa = $('Resolve User Row').first().json.resolved_key;
const now = Date.now();

// Global store menggunakan $workflow static data
const staticData = $getWorkflowStaticData('global');
const rateLimits = staticData.rateLimits || {};

const userKey = `rl_${userWa}`;
const windowMs = 60000; // 1 menit
const maxMessages = 5;

if (!rateLimits[userKey]) {
  rateLimits[userKey] = { count: 1, windowStart: now };
} else {
  const elapsed = now - rateLimits[userKey].windowStart;
  if (elapsed > windowMs) {
    // Reset window baru
    rateLimits[userKey] = { count: 1, windowStart: now };
  } else {
    rateLimits[userKey].count++;
  }
}

staticData.rateLimits = rateLimits;

const isRateLimited = rateLimits[userKey].count > maxMessages;

if (isRateLimited) {
  console.log(`⛔ RATE LIMITED: ${userWa} sudah ${rateLimits[userKey].count} pesan dalam 1 menit`);
  return [];
}

console.log(`✅ RATE OK: ${userWa} pesan ke-${rateLimits[userKey].count}`);
return [$input.first()];

// ============================================================
// HUMAN-IN-THE-LOOP CHECK — bot_mode 'OFF' = admin pegang manual, bot berhenti.
// Sumbernya Resolve User Row, bukan pembacaan STATS tersendiri: node lama
// 'Read STATS for HITL' membaca ulang seluruh tab ~2 detik setelah
// 'Read User STATS', untuk nilai yang tidak berubah di antara keduanya.
// Pemeriksaan ulang yang berarti tetap ada, setelah debounce, di
// 'Re-Read STATS Debounce'.
// ============================================================
const r = $('Resolve User Row').first().json;
const botMode = String(r.bot_mode || '').trim().toUpperCase();

if (botMode === 'OFF') {
  console.log('👨‍💼 HITL AKTIF — admin sedang handle manual, bot berhenti.');
  return [];
}

console.log(`🤖 Bot mode AKTIF (bot_mode="${botMode}") — lanjut.`);
return [$input.first()];

// NODE: Cek_user_status
// ====================================================================
// CEK_USER_STATUS - gate HITL post-debounce + gabung MSG_BUFFER +
// siapkan SYSTEM_DATA (intro user baru, unit/budget tersimpan).
// Perubahan 2026-07-17: (1) INTRO "Saya VIRA" -> "Saya Vira",
// (2) inject TANGGAL_SEKARANG (WIB) ke [SYSTEM_DATA].
// [V2 - VISION] 2026-08-07: baris MSG_BUFFER yang isinya HANYA media
// (message kosong) TIDAK lagi dibuang. URL gambar dalam window debounce
// dikumpulkan ke `vision_images` untuk dianalisa Claude Haiku.
// ====================================================================
const cc = $('Chat Counter').first().json;
const resolve = $('Resolve User Row').first().json;
const resolvedKey = resolve.resolved_key;
const cfg = (() => { try { return $('Parse Config').first().json.config || {}; } catch (e) { return {}; } })();

const debounceItem = $('Re-Read STATS Debounce').first();
const debounceRow = (debounceItem && debounceItem.json) ? debounceItem.json : {};
const botModeNow = String(debounceRow['bot_mode'] || '').trim().toUpperCase();
if (botModeNow === 'OFF') {
  console.log('HITL (post-debounce): bot_mode OFF - berhenti, admin handle manual.');
  return [];
}

const doneTs = Number(debounceRow['buffer_done_ts'] || 0) || 0;
const myTs = Number(cc.process_start_ts) || 0;
let bufRows = [];
try {
  bufRows = $('Read MSG_BUFFER').all().map(i => i.json).filter(r => !!r);
} catch (e) { console.warn('Read MSG_BUFFER tidak terbaca:', e.message); }

const MAX_AGE_MS = 30 * 60 * 1000;
// [V2] baris dianggap valid kalau punya teks ATAU punya media.
let msgs = bufRows
  .map(r => ({
    ts: Number(r.ts) || 0,
    message: String(r.message ?? '').trim(),
    media_url: String(r.media_url ?? '').trim(),
    media_type: String(r.media_type ?? '').trim().toLowerCase()
  }))
  .filter(r => r.ts > doneTs && r.ts <= myTs && (myTs - r.ts) < MAX_AGE_MS)
  .filter(r => r.message !== '' || (r.media_url !== '' && r.media_type === 'image') || r.media_type === 'other')
  .sort((a, b) => a.ts - b.ts);

// Fallback: buffer gagal dibaca / kolom media belum ada -> pakai pesan ini saja.
if (!msgs.length) {
  const fb = {
    ts: myTs,
    message: String(cc.original_message || '').trim(),
    media_url: String(cc.media_url || '').trim(),
    media_type: String(cc.media_kind || 'none')
  };
  if (fb.message !== '' || fb.media_url !== '' || fb.media_type === 'other') msgs = [fb];
}

const userMessage = msgs.map(r => r.message).filter(Boolean).join('\n');

// [V2] kumpulkan gambar dalam window ini (dedup URL, ambil yang terbaru)
const maxImg = Math.max(1, Number(cfg.vision_max_images ?? 3) || 3);
const seenUrl = new Set();
const allImages = [];
for (const r of msgs) {
  if (r.media_type === 'image' && r.media_url && !seenUrl.has(r.media_url)) {
    seenUrl.add(r.media_url);
    allImages.push({ url: r.media_url, ts: r.ts });
  }
}
const visionImages = allImages.slice(-maxImg);
const imagesDropped = Math.max(0, allImages.length - visionImages.length);
const otherMediaCount = msgs.filter(r => r.media_type === 'other').length;
const hasImage = visionImages.length > 0;
// [V2.1] hanya mode 'full' yang memanggil Claude. 'ack'/'off' = nol biaya.
const visionMode = String(cfg.vision_mode || 'full').toLowerCase();
const visionOn = hasImage && visionMode === 'full';

// Teks yang dilihat AI di [USER QUERY]. Kalau user cuma kirim lampiran tanpa
// caption, JANGAN pakai kata "gambar"/"foto" di sini - regex wantsMedia di
// Preprocess akan kena dan Vira malah kirim brosur.
const userQueryText = userMessage !== ''
  ? userMessage
  : ((hasImage || otherMediaCount > 0) ? '(user mengirim lampiran tanpa teks)' : '');

const greetingSent = String(debounceRow['greeting_sent'] || resolve.greeting_sent || '').trim().toUpperCase();
const isNewUser = greetingSent !== 'Y';

const TTL_S = 60 * 86400;
const nowS = Math.floor(Date.now() / 1000);
const uiTs = Number(debounceRow['unit_interest_ts'] || resolve.unit_interest_ts || 0) || 0;
const uiFresh = uiTs > 0 && (nowS - uiTs) <= TTL_S;
const unitInterest = uiFresh ? String(debounceRow['unit_interest'] || resolve.unit_interest || '').trim() : '';
const brTs = Number(debounceRow['budget_range_ts'] || resolve.budget_range_ts || 0) || 0;
const brFresh = brTs > 0 && (nowS - brTs) <= TTL_S;
const budgetRange = brFresh ? String(debounceRow['budget_range'] || resolve.budget_range || '').trim() : '';

// PROFIL USER (nama lengkap + lokasi_kerja)
const namaLengkap = String(debounceRow['nama_lengkap'] || resolve.nama_lengkap || '').trim();
const lokasi_kerja     = String(debounceRow['lokasi_kerja']     || resolve.lokasi_kerja     || '').trim();
const needName     = !namaLengkap;
const needDomicile = !lokasi_kerja;
const askProfileNow = isNewUser && (needName || needDomicile);
const askProfileTarget = !askProfileNow ? 'NO'
  : (needName && needDomicile) ? 'nama+lokasi_kerja'
  : (needName ? 'nama' : 'lokasi_kerja');
const needUnit = !unitInterest || unitInterest === 'UNKNOWN';
const askUnitNow = isNewUser && needUnit;
const askUnitTarget = askUnitNow ? 'tipe unit (subsidi/komersial)' : 'NO';

// PENDING SURVEY (register #1) - slot survey lintas giliran dari STATS, TTL 48 jam.
const PENDING_TTL_S = 48 * 3600;
const psTs = Number(debounceRow['pending_survey_ts'] || resolve.pending_survey_ts || 0) || 0;
const psFresh = psTs > 0 && (nowS - psTs) <= PENDING_TTL_S;
const psTgl = psFresh ? String(debounceRow['pending_survey_tanggal'] || resolve.pending_survey_tanggal || '').trim() : '';
const psJam = psFresh ? String(debounceRow['pending_survey_jam'] || resolve.pending_survey_jam || '').trim() : '';
const psUnit = psFresh ? String(debounceRow['pending_survey_unit'] || resolve.pending_survey_unit || '').trim() : '';
const hasPendingSurvey = !!(psTgl || psJam || psUnit);

// Tanggal & jam sekarang dlm WIB - sumber kebenaran tanggal utk AI.
const nowWIB = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Jakarta' }));
const pad2 = n => String(n).padStart(2, '0');
const HARI = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
const tanggalSekarang = `${nowWIB.getFullYear()}-${pad2(nowWIB.getMonth() + 1)}-${pad2(nowWIB.getDate())}`;
const hariSekarang = HARI[nowWIB.getDay()];
const jamSekarang = `${pad2(nowWIB.getHours())}:${pad2(nowWIB.getMinutes())}`;

const aiSystemData = `[SYSTEM_DATA]
USER_WA: ${resolvedKey}
IS_NEW_USER: ${isNewUser}
NAMA_LENGKAP: ${namaLengkap || 'UNKNOWN'}
TANGGAL_SEKARANG: ${tanggalSekarang} (${hariSekarang}) ${jamSekarang} WIB

CRITICAL INSTRUCTION:
${isNewUser
  ? 'USER BARU. Buka dengan perkenalan sesuai bagian PERKENALAN di instruksimu — susun dengan kalimatmu sendiri, jangan disalin persis, lalu gabungkan dengan jawaban atas pertanyaannya dalam SATU pesan.'
  : 'User lama. JANGAN memperkenalkan diri lagi, lanjutkan percakapan secara natural.'}

[USER QUERY]
${userQueryText}`;

return [{
  json: {
    ...cc,
    resolved_key: resolvedKey,
    ai_input_text: aiSystemData,
    user_message_final: userMessage,
    is_new_user: isNewUser,
    unit_interest_db: unitInterest,
    budget_range_db: budgetRange,
    nama_lengkap_db: namaLengkap,
    lokasi_kerja_db: lokasi_kerja,
    pending_survey_tanggal_db: psTgl,
    pending_survey_jam_db: psJam,
    pending_survey_unit_db: psUnit,
    ask_profile: askProfileTarget,
    buffer_done_ts_old: doneTs,
    // ---- [V2 VISION] ----
    vision_images: visionImages,
    vision_images_dropped: imagesDropped,
    has_image: hasImage,
    vision_on: visionOn,
    other_media_count: otherMediaCount,
    user_query_text: userQueryText,
    vision_mode: visionMode
  }
}];

// ====================================================================
// DETECT LEAD SOURCE (BARU) — deteksi sumber traffic dari pesan pertama.
// Rule-based murah; default "Organik". Tulis sekali (preserve first-touch).
// ====================================================================
// [V2 VISION] baca dari INPUT, bukan langsung dari Cek_user_status.
// Node 'Rakit Konteks Gambar' menyisipkan deskripsi gambar ke ai_input_text;
// kalau di sini masih ambil dari Cek_user_status, sisipan itu ketimpa.
const pre = $input.first().json;
const resolve = $('Resolve User Row').first().json;
const cfg = (() => { try { return $('Parse Config').first().json.config || {}; } catch(e){ return {}; } })();
const firstMsg = String(pre.user_message_final || pre.original_message || '').toLowerCase();

const DEFAULT_MAP = [
  { source:'Instagram', keywords:['instagram','ig','insta','dari ig','lihat di ig','story ig'] },
  { source:'Facebook',  keywords:['facebook','fb','dari fb','lihat di fb','marketplace'] },
  { source:'Google',    keywords:['google','search','nyari di google','gmaps','maps'] },
  { source:'TikTok',    keywords:['tiktok','tt','dari tiktok'] },
  { source:'WhatsApp',  keywords:['broadcast','wa blast','katalog wa'] },
];
const MAP = (Array.isArray(cfg.lead_source_map) && cfg.lead_source_map.length) ? cfg.lead_source_map : DEFAULT_MAP;

let detected = '';
for (const m of MAP) {
  const kws = (m.keywords || []);
  if (kws.some(k => firstMsg.includes(String(k).toLowerCase()))) { detected = m.source; break; }
}
if (!detected) detected = 'Organik';

const existing = String(resolve.lead_source_db || '').trim();
const finalSource = existing || detected;   // preserve sumber pertama

return [{ json: { ...pre, lead_source_detected: detected, lead_source_final: finalSource } }];

// ============================================
// PREPROCESS - CONTEXT DETECTION (domain properti PCR)
// Deteksi tipe unit, budget, intent + INJECT KALENDER WIB ke AI.
// Mekanisme dipertahankan: [SYSTEM_DATA] + [CONTEXT] + [USER QUERY]
// ============================================
const json = $input.item.json;
const fullMessage = json.ai_input_text || json.message || json.text || '';

const cfg = (() => { try { return $('Parse Config').first().json.config || {}; } catch (e) { return {}; } })();

// ── KALENDER WIB (anti-halusinasi tanggal) ──
// LLM buruk berhitung kalender -> jangan suruh hitung, kasih tabelnya.
const DAY_ID = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
const pad = n => String(n).padStart(2, '0');
const fmtISO = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const nowWIB = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Jakarta' }));

const openH = Number(cfg.survey_open_hour ?? 8);
const closeH = Number(cfg.survey_close_hour ?? 17);
// 🔶 Hari tutup survey. Default: Minggu (0). Ubah ke [] kalau buka tiap hari.
const closedDays = Array.isArray(cfg.survey_closed_days) ? cfg.survey_closed_days.map(Number) : [];

const calendarLines = [];
for (let i = 1; i <= 7; i++) {
  const d = new Date(nowWIB.getFullYear(), nowWIB.getMonth(), nowWIB.getDate() + i);
  const rel = i === 1 ? ' (besok)' : (i === 2 ? ' (lusa)' : '');
  const tutup = closedDays.includes(d.getDay()) ? ' [TUTUP - jangan tawarkan]' : '';
  calendarLines.push(`  ${DAY_ID[d.getDay()]}${rel} = ${fmtISO(d)}${tutup}`);
}

const calendarBlock =
  `TODAY: ${fmtISO(nowWIB)} (${DAY_ID[nowWIB.getDay()]})\n` +
  `NOW_WIB: ${pad(nowWIB.getHours())}:${pad(nowWIB.getMinutes())}\n` +
  `JAM_OPERASIONAL_SURVEY: ${pad(openH)}:00-${pad(closeH)}:00\n` +
  `HARI_KE_TANGGAL (WAJIB pakai daftar ini, DILARANG menghitung/menebak tanggal sendiri):\n` +
  calendarLines.join('\n');

// ── PARSE INPUT ──
let actualUserMessage = '';
if (fullMessage.includes('[USER QUERY]')) {
  actualUserMessage = (fullMessage.split('[USER QUERY]')[1] || '').trim();
} else {
  actualUserMessage = String(fullMessage).trim();
}

let isNewUser = false, unitInterestDB = '', budgetRangeDB = '';
if (fullMessage.includes('[SYSTEM_DATA]')) {
  const m = fullMessage.match(/IS_NEW_USER:\s*(\w+)/i); if (m) isNewUser = m[1].toLowerCase() === 'true';
  const u = fullMessage.match(/UNIT_INTEREST:\s*([^\n]+)/i); if (u) { const v = u[1].trim(); if (v && v.toUpperCase() !== 'UNKNOWN') unitInterestDB = v; }
  const b = fullMessage.match(/BUDGET_RANGE:\s*([^\n]+)/i); if (b) { const v = b[1].trim(); if (v && v.toUpperCase() !== 'UNKNOWN') budgetRangeDB = v; }
}

const message = actualUserMessage.toLowerCase();
const userPhone = json.user_wa || json.from || 'unknown';

// deteksi tipe unit — WAJIB lengkap "NN/NN". Semua tipe PCR punya slash,
// jadi "tipe 36" tanpa slash = TIDAK VALID (ini akar bug memori "Tipe 36").
const canonType = (s) => { const m = String(s).match(/(\d{2,3})\s*\/\s*(\d{2,3})/); return m ? `Tipe ${m[1]}/${m[2]}` : null; };
const addUnit = (arr, s) => { const c = canonType(s); if (c && !arr.includes(c)) arr.push(c); };

let units = [];
const typeRe = /tipe\s*(\d{2,3})\s*\/\s*(\d{2,3})/gi; // slash WAJIB (dulu opsional -> "tipe 36" ketangkep)
let tm;
while ((tm = typeRe.exec(message)) !== null) addUnit(units, `${tm[1]}/${tm[2]}`);

// fallback dari DB: saring lewat canonType supaya nilai lama yang korup ("Tipe 36") tidak ikut
if (!units.length && unitInterestDB) { for (const s of unitInterestDB.split(',')) addUnit(units, s); }

// budget mention (mis. "500 juta", "1.2 M")
let budgetMention = '';
const bmatch = message.match(/(\d+(?:[.,]\d+)?)\s*(jt|juta|m\b|miliar|milyar)/i);
if (bmatch) budgetMention = bmatch[0].trim();

const askingPrice = /harga|biaya|berapa|nyicil|cicil|angsuran|\bdp\b|kpr|bayar|murah|mahal|promo/i.test(message);
const askingKPR = /kpr|cicil|angsuran|\bdp\b|tenor|bunga|bank|simulasi|subsidi/i.test(message);
const askingLokasi = /lokasi|alamat|dimana|di mana|maps|arah|jalan|akses|tol|dekat|deket|stasiun/i.test(message);
const askingLegalitas = /shm|hgb|sertifikat|legalitas|imb|pbb|surat|akad|notaris|balik nama/i.test(message);
const askingFasilitas = /fasilitas|keamanan|cctv|masjid|taman|kolam|security|one gate|cluster/i.test(message);
const wantsSurvey = /survey|survei|kunjungan|lihat lokasi|liat lokasi|liat unit|lihat unit|ke lokasi|datang|show ?unit|kunjung/i.test(message);
const wantsMedia = /brosur|siteplan|site plan|denah|katalog|gambar|foto|price ?list/i.test(message);
const discussingUnit = /unit|tipe|rumah|cluster|kavling|hook|ready|indent/i.test(message) || units.length > 0;

// User membalas slot ("jam 10 pagi bs", "senin aja") -> wantsSurvey regex TIDAK kena,
// padahal ini lanjutan penjadwalan. Deteksi terpisah supaya CONTEXT tetap terpasang.
const mentionsDateTime = /\b(senin|selasa|rabu|kamis|jumat|jum'at|sabtu|minggu|besok|lusa|hari ini|akhir pekan|weekend)\b/i.test(message)
  || /\bjam\s*\d{1,2}|\d{1,2}[:.]\d{2}|\b\d{1,2}\s*(pagi|siang|sore|malam)\b/i.test(message)
  || /\b\d{1,2}[\/\-]\d{1,2}(?:[\/\-]\d{2,4})?\b/.test(message);

let aiContext = '';
if (askingPrice) aiContext += `User menanyakan harga. Sebut kisaran dari DATA PRODUK lalu arahkan ke Steven untuk angka final. Jangan menawar, jangan memberi diskon. `;
else if (budgetMention) aiContext += `User menyebut kisaran anggaran ${budgetMention}. Kaitkan ke paket yang paling masuk akal, tetap pakai kisaran resmi. `;
if (wantsMedia) aiContext += `User meminta file. Kalau ada yang cocok di DAFTAR MEDIA, pasang [SEND_MEDIA: <nama-link>] persis seperti tertulis di daftar. Kalau tidak ada yang cocok, jangan pasang tag apa pun dan jangan mengarang nama link. `;
if (wantsSurvey || mentionsDateTime) aiContext += `User menyinggung waktu atau jadwal. Kamu tidak bisa menjadwalkan apa pun sendiri — kalau dia ingin bicara langsung dengan Steven, pakai [TALK_TO_ADMIN]. Jangan menjanjikan jam atau tanggal. `;

// ── RAKIT INPUT AI ──
let systemDataBlock = '';
if (fullMessage.includes('[USER QUERY]')) systemDataBlock = fullMessage.split('[USER QUERY]')[0].trim();

let enhancedInput = '';
if (systemDataBlock) {
  // sisipkan kalender ke dalam blok [SYSTEM_DATA], sebelum CRITICAL INSTRUCTION
  if (systemDataBlock.includes('CRITICAL INSTRUCTION')) {
    enhancedInput += systemDataBlock.replace('CRITICAL INSTRUCTION', calendarBlock + '\n\nCRITICAL INSTRUCTION') + `\n\n`;
  } else {
    enhancedInput += systemDataBlock + `\n` + calendarBlock + `\n\n`;
  }
} else {
  enhancedInput += `[SYSTEM_DATA]\n` + calendarBlock + `\n\n`;
}
if (aiContext.trim()) enhancedInput += `[CONTEXT: ${aiContext.trim()}]\n\n`;
enhancedInput += `[USER QUERY]\n${actualUserMessage}`;

return {
  userPhone,
  actualUserMessage,
  fullMessage,
  messageLower: message,
  isNewUser,
  unitInterestDB,
  budgetRangeDB,
  units,
  budgetMention,
  askingPrice,
  askingKPR,
  askingLokasi,
  askingLegalitas,
  askingFasilitas,
  wantsSurvey,
  wantsMedia,
  mentionsDateTime,
  discussingUnit,
  today_wib: fmtISO(nowWIB),
  now_wib_ts: nowWIB.getTime(),
  aiContext: aiContext.trim(),
  ai_input_text: enhancedInput
};

// ===== FAQ RETRIEVE — VIRA Steven =====
// Pencarian FAQ leksikal (TF-IDF sederhana + sinonim domain).
// Sumber datanya `katalog` dari cache, bukan $('Read FAQ') langsung: saat cache HIT
// node Sheets-nya tidak dijalankan sama sekali.
// Blok `data_context` warisan Persada dibuang — isinya dibangun dari $('Read PRODUK Data')
// yang sudah tidak ada sejak node itu direname, jadi selalu kosong, dan tidak ada satu
// node pun yang membacanya (Rakit Konteks menyusun program_context & links_context sendiri).
try {
  const inp = $input.first().json;
  const pre = $('Preprocess - Context Detection').first().json;
  const query = pre.actualUserMessage || '';
  const katalog = inp.katalog || { faq: [] };

  const STOP = new Set(['yang','untuk','dan','di','ke','dari','itu','ini','apa','apakah','bisa','kah','ya','yaa','kak','min','dong','sih','kok','aja','ada','gimana','bagaimana','saya','aku','nya','kalau','atau','juga','sudah','belum','mau','dengan','pada','adalah','tolong','mohon','halo','hai','permisi','terima','kasih','sama','buat','soal','tentang','nih','ga','gak','engga','tidak','dll','yg','utk','kamu','kita','gitu','banget','emang','memang']);

  // Kelompok sinonim domain VIRA Steven (jasa AI customer service), bukan properti.
  // Kata pertama tiap grup jadi wakilnya.
  const GROUPS = [
    ['harga','biaya','tarif','bayar','paket','basic','premium','langganan','bulanan','mahal','murah','budget','nego','setup','token','kontrak','berhenti'],
    ['fitur','kemampuan','fungsi','follow','followup','laporan','analitik','invoice','jadwal','multibahasa','inggris','mandarin'],
    ['media','foto','gambar','video','brosur','katalog','file','dokumen','demo','contoh','bukti','portfolio','tangkapan'],
    ['aman','keamanan','privasi','bocor','rahasia','akses','data'],
    ['proses','lama','durasi','waktu','golive','mulai','siapkan','persiapan','maintenance'],
    ['deck','pitch','proposal','penawaran','presentasi'],
    ['steven','klien','pengalaman','siapa','background','qa'],
    ['whatsapp','wa','nomor','device','aplikasi','install','internet','server','sheets','spreadsheet'],
    ['error','gangguan','down','mati','rusak','gagal','ramai','lonjakan','kuat'],
    ['bot','ai','robot','manusia','admin','chatbot','template','persona','gaya'],
  ];
  const SYN = {}; for (const g of GROUPS) for (const w of g) SYN[w] = g[0];

  const stem = (t) => { let w = t; for (const s of ['nya','kah','lah','kan','an','i']) if (w.length - s.length >= 4 && w.endsWith(s)) { w = w.slice(0, -s.length); break; } for (const p of ['meng','meny','mem','men','peng','peny','pem','pen','ber','ter','di','se','ke','me','pe']) if (w.length - p.length >= 4 && w.startsWith(p)) { w = w.slice(p.length); break; } return w; };
  const tok = (s) => (s || '').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').split(/\s+/).filter(Boolean).filter(t => !STOP.has(t)).map(t => { const a = SYN[t]; if (a) return a; const st = stem(t); return SYN[st] || st; }).filter(t => t.length >= 2 && !STOP.has(t));

  const faq = (katalog.faq || []).filter(r => r && r.Pertanyaan && r.Jawaban
    && /^\s*(aktif|active|on|ya)\s*$/i.test(String(r.Status || 'Aktif')));
  const docs = faq.map(r => ({ row: r, toks: tok(r.Pertanyaan) }));
  const Nn = docs.length, df = {};
  for (const dd of docs) for (const t of new Set(dd.toks)) df[t] = (df[t] || 0) + 1;
  const idf = (t) => Math.log((Nn + 1) / ((df[t] || 0) + 1)) + 1;

  // Boost mengikuti nama Kategori yang benar-benar ada di tab FAQ VIRA Steven.
  const boost = {};
  if (pre.askingPrice) boost['Harga'] = 1.25;
  if (pre.wantsMedia)  boost['Fitur'] = 1.15;

  const qToks = [...new Set(tok(query))];
  let faq_context = '';
  if (qToks.length && docs.length) {
    const scored = docs.map(dd => {
      const dset = new Set(dd.toks);
      let s = 0, m = 0;
      for (const t of qToks) if (dset.has(t)) { s += idf(t); m++; }
      s *= (boost[dd.row.Kategori] || 1.0);
      return { row: dd.row, score: s, matched: m };
    }).sort((a, b) => b.score - a.score);
    const top = scored[0];
    const FLOOR = 2.5, needCov = qToks.length >= 3 ? 2 : 1;
    if (top.score >= FLOOR && top.matched >= needCov) {
      const kept = scored.filter(x => x.score >= 0.45 * top.score && x.matched >= 1).slice(0, 4);
      faq_context = kept.map(x => `Q: ${x.row.Pertanyaan}\nA: ${x.row.Jawaban}`).join('\n\n');
    }
  }

  return [{ json: { ...pre, katalog, faq_context }, pairedItem: { item: 0 } }];
} catch (e) {
  const pre = ($('Preprocess - Context Detection').first() || { json: {} }).json || {};
  const katalog = ($input.first().json || {}).katalog || { faq: [], program: [], links: [], about: [] };
  return [{ json: { ...pre, katalog, faq_context: '', faq_error: String(e) }, pairedItem: { item: 0 } }];
}

// ── Process All — VIRA Steven ──
// Ditulis ulang dari versi Persada oleh _transform.py. Jangan diedit langsung di n8n.
const item = $input.first();
let aiOutput = '';
if (item?.json?.content && Array.isArray(item.json.content) && item.json.content.length > 0) {
  aiOutput = item.json.content[0].text || '';
} else {
  aiOutput = item?.json?.output || item?.json?.text || '';
}
console.log('AI Output preview:', aiOutput.substring(0, 300));

const chatCounter = $('Chat Counter').first().json;
const preprocess  = $('Preprocess - Context Detection').first().json;
const cfg  = (() => { try { return $('Parse Config').first().json.config || {}; } catch (e) { return {}; } })();
const prev = (() => { try { return $('Resolve User Row').first().json || {}; } catch (e) { return {}; } })();
const originalMessage = chatCounter.original_message || '';
const isNewUser = preprocess?.isNewUser || false;

// ── util ──
// buang karakter kontrol, rapikan spasi, batasi panjang
const BERSIH = (s, max) => String(s ?? '')
  .split('').filter(ch => ch.charCodeAt(0) >= 32).join('')
  .replace(/\s+/g, ' ').trim().slice(0, max || 200);
// nilai yang artinya "tidak ada isi" — termasuk placeholder yang diminta ke AI
const KOSONG = (s) => {
  const t = BERSIH(s).toLowerCase().replace(/[.\s]+$/, '');
  return !t || t === '-' || t === '...' || t === 'belum disebut' || t === 'belum tahu'
      || t === 'tidak disebut' || t === 'n/a' || t === 'na' || t === 'null' || t === 'undefined';
};

// ── TAG sederhana ──
const isTalkToAdmin = aiOutput.includes('[TALK_TO_ADMIN]');
const isUnknown     = aiOutput.includes('[UNKNOWN]');

// ── TAG: [SEND_MEDIA: key] — maksimal 2, tanpa fallback frasa ──
let isSendMedia = false, mediaKey = '';
const mediaKeysAll = [...new Set(
  [...aiOutput.matchAll(/\[\s*SEND_MEDIA\s*(?::\s*([^\]]*))?\]/gi)]
    .map(m => (m[1] || '').trim().toLowerCase())
    .filter(Boolean)
)].slice(0, 2);
if (mediaKeysAll.length) { isSendMedia = true; mediaKey = mediaKeysAll[0]; }

// ── TAG: [FACTS ...] + merge persist ──
const FACT_FIELDS = ['nama_lengkap', 'nama_bisnis', 'industri', 'masalah_utama',
                     'volume_chat', 'budget_range', 'minat_paket'];
const PANJANG = { masalah_utama: 300, nama_lengkap: 60 };
const factsMatch = aiOutput.match(/\[\s*FACTS\b([^\]]*)\]/i);
const facts = {};
if (factsMatch && factsMatch[1]) {
  const isi = factsMatch[1];
  for (const f of FACT_FIELDS) {
    const m = isi.match(new RegExp(f + '\\s*=\\s*"([^"]*)"', 'i'));
    if (m) facts[f] = m[1];
  }
  // alias: prompt versi awal memakai nama="..." untuk nama_lengkap
  const mn = isi.match(/(^|[\s\[])nama\s*=\s*"([^"]*)"/i);
  if (mn && facts.nama_lengkap === undefined) facts.nama_lengkap = mn[2];
}
const merged = {}, changed = {};
for (const f of FACT_FIELDS) {
  const max  = PANJANG[f] || 120;
  const baru = KOSONG(facts[f]) ? '' : BERSIH(facts[f], max);
  const lama = BERSIH(prev[f], max);
  merged[f]  = baru || lama;
  changed[f] = merged[f] !== '' && merged[f] !== lama;
}

// ── TAG: [DECK_REQUEST] ... [/DECK_REQUEST] ──
const DECK_FIELDS = ['nama', 'jabatan', 'nama_bisnis', 'industri', 'deskripsi_bisnis',
  'target_pelanggan', 'channel', 'sumber_leads', 'volume_chat_harian', 'jam_operasional',
  'siapa_balas_chat', 'biaya_admin_bulanan', 'sistem_sekarang', 'masalah_utama', 'pain_points',
  'aksi_utama', 'alur_setelah_chat', 'pertanyaan_tersering', 'fitur_diminati', 'nilai_transaksi',
  'prospek_per_bulan', 'minat_paket', 'budget_range', 'deadline', 'urgensi', 'bahasa_deck', 'catatan'];

let isDeckRequest = false, deckRejected = false, deckMissing = [];
const deckRequest = {};
for (const f of DECK_FIELDS) deckRequest[f] = '';

const deckBlock = aiOutput.match(/\[\s*DECK_REQUEST\s*\]([\s\S]*?)\[\s*\/\s*DECK_REQUEST\s*\]/i);
if (deckBlock) {
  isDeckRequest = true;
  const dikenal = new Set(DECK_FIELDS);
  for (const baris of deckBlock[1].split('\n')) {
    const m = baris.match(/^\s*([A-Za-z_]+)\s*:\s*(.*)$/);
    if (!m) continue;                                  // baris kosong / bukan pasangan key:value
    const k = m[1].toLowerCase();
    if (!dikenal.has(k)) continue;                     // key asing diabaikan, bukan digagalkan
    deckRequest[k] = KOSONG(m[2]) ? '' : BERSIH(m[2], 500);
  }
  // fakta yang sudah dipastikan sistem menang atas tulisan AI di blok ini
  if (!deckRequest.nama && merged.nama_lengkap) deckRequest.nama = merged.nama_lengkap;
  const DARI_FACTS = [['nama_bisnis', 'nama_bisnis'], ['industri', 'industri'],
                      ['masalah_utama', 'masalah_utama'], ['minat_paket', 'minat_paket'],
                      ['budget_range', 'budget_range'], ['volume_chat_harian', 'volume_chat']];
  for (const [dk, fk] of DARI_FACTS) {
    if (!deckRequest[dk] && merged[fk]) deckRequest[dk] = merged[fk];
  }
  // GATE TINGKAT 1 — brief tanpa ketiganya tidak cukup untuk menyusun deck
  deckMissing = ['nama_bisnis', 'industri', 'masalah_utama'].filter(f => !deckRequest[f]);
  if (deckMissing.length) {
    isDeckRequest = false;
    deckRejected = true;
    console.warn('DECK_REQUEST ditolak, tingkat 1 belum lengkap: ' + deckMissing.join(', '));
  }
}
const bahasaMerged = (KOSONG(deckRequest.bahasa_deck) ? '' : BERSIH(deckRequest.bahasa_deck, 20))
                     || BERSIH(prev.bahasa, 20);

// ── CLEAN OUTPUT (buang semua tag) ──
let cleanOutput = aiOutput
  .replace(/\[\s*DECK_REQUEST\s*\][\s\S]*?\[\s*\/\s*DECK_REQUEST\s*\]/gi, '')
  .replace(/\[\s*\/?\s*DECK_REQUEST\s*\][\s\S]*$/gi, '')   // blok tak tertutup (output terpotong)
  .replace(/\[\s*SEND_MEDIA\s*(?::[^\]]*)?\]/gi, '')
  .replace(/\[TALK_TO_ADMIN\]/gi, '')
  .replace(/\[UNKNOWN\]/gi, '')
  .replace(/\[\s*FACTS\b[^\]]*\]/gi, '');

const preInternalStrip = cleanOutput;
const internalKeywords = ['berdasarkan faq','berdasarkan data','menurut data','dari faq','dari sheet','data terverifikasi','faq relevan','data yang tersedia','saya cek data','saya cek faq','saya cek sheet','cek di sheet','cek di database'];
const keywordPattern = internalKeywords.join('|');
cleanOutput = cleanOutput.replace(new RegExp(`^\\s*([^.!?]*?(${keywordPattern})[^.!?]*[.!?]\\s*)`, 'i'), '');
cleanOutput = cleanOutput.replace(new RegExp(`^\\s*(${keywordPattern}).*?(\\n|\\.|$)`, 'i'), '');
cleanOutput = cleanOutput.replace(/^\s*(Berdasarkan|Menurut|Dari)\s+(data|faq|sheet|referensi)[^.!?]*[.!?]\s*/i, '');
if (!cleanOutput.trim() && preInternalStrip.trim()) cleanOutput = preInternalStrip;
cleanOutput = cleanOutput.trim();

// bersihkan markdown (URL di-mask dulu supaya tidak ikut terpotong)
const urlRegex = /https?:\/\/[^\s)]+/g;
const maskedUrls = [];
cleanOutput = cleanOutput.replace(urlRegex, (m) => { maskedUrls.push(m); return `\x00URL${maskedUrls.length - 1}\x00`; });
cleanOutput = cleanOutput
  .replace(/\*\*([^*]+)\*\*/g, '$1').replace(/\*([^*]+)\*/g, '$1').replace(/_([^_]+)_/g, '$1')
  .replace(/~~([^~]+)~~/g, '$1').replace(/`([^`]+)`/g, '$1').replace(/[\*_~`]/g, '');
cleanOutput = cleanOutput
  .replace(/(\d)\s*[—–]\s*(\d)/g, '$1-$2').replace(/\s*[—–]\s*/g, ', ').replace(/\s*;\s*/g, ', ')
  .replace(/\s{2,}/g, ' ').replace(/\s+([,.])/g, '$1').replace(/,\s*,/g, ',').trim();
cleanOutput = cleanOutput.replace(/\x00URL(\d+)\x00/g, (_, idx) => maskedUrls[parseInt(idx)]);
cleanOutput = cleanOutput.replace(/(^|\n)([a-z])/g, (m, p1, p2) => p1 + p2.toUpperCase());

if (!cleanOutput || cleanOutput.trim() === '') {
  cleanOutput = isUnknown
    ? 'Maaf yaa, untuk yang ini aku belum tahu. Nanti aku cek dulu dan kabari lagi.'
    : 'Maaf, ada kendala sebentar. Boleh diketik ulang yaa.';
}

// ── FAIL LOUD: brief ditolak tapi balasan terlanjur menjanjikan deck ──
// Tag ditolak harus MENGUBAH balasan, bukan cuma dibuang — kalau tidak, prospek
// diberi janji yang tidak ada catatannya di mana pun. Override hanya dilakukan
// kalau balasannya memang menjanjikan; kalau tidak, tag cukup didiamkan.
if (deckRejected) {
  const low = cleanOutput.toLowerCase();
  const menjanjikan = /(deck|proposal|penawaran)/.test(low)
                   && /(susun|siapkan|buatkan|kirim|hubungi|kabari)/.test(low);
  if (menjanjikan) {
    const TANYA = {
      nama_bisnis:   'Boleh tahu nama bisnisnya dulu kak? Biar aku catat dengan benar.',
      industri:      'Bisnisnya bergerak di bidang apa kak?',
      masalah_utama: 'Sekarang yang paling bikin repot soal chat masuk itu apa kak?',
    };
    cleanOutput = TANYA[deckMissing[0]] || 'Boleh cerita sedikit soal bisnisnya kak?';
    console.warn('Balasan diganti: janji deck tanpa brief tingkat 1.');
  }
}

// ── RESOLVE MEDIA URL + caption dari LINKS ──
// Disederhanakan dari Persada: kolom 'Tipe Unit' tidak ada di sheet VIRA Steven,
// jadi seluruh penyempitan berbasis tipe unit dibuang. Gate ambigu & eskalasi
// manual dipertahankan apa adanya.
let mediaUrl = '', mediaCaption = '';
let isMediaManual = false, mediaRequestSummary = '';
let isMediaAmbiguous = false, mediaCandidates = [], linkAktifNama = [];
if (isSendMedia) {
  let linkRows = [];
  try { linkRows = $('Rakit Konteks').first().json.katalog.links || []; } catch (e) {}
  const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
  const active = linkRows.filter(r => /^\s*(aktif|active|on|ya)\s*$/i.test(String(r['Status'] || '')));
  linkAktifNama = active.map(r => String(r['Nama Link'] || '').trim()).filter(Boolean);

  // Drive 'uc?export=download' membalas halaman konfirmasi virus-scan (HTML) untuk
  // file besar, bukan byte filenya. Bentuk usercontent + confirm=t melewati halaman itu.
  const rapikanUrl = (u) => {
    const s = String(u || '').trim();
    const m = s.match(/^https?:\/\/(?:drive|docs)\.google\.com\/(?:uc\?(?:[^#]*&)?id=|file\/d\/)([A-Za-z0-9_-]{10,})/);
    return m ? ('https://drive.usercontent.google.com/download?id=' + m[1] + '&export=download&confirm=t') : s;
  };

  const resolveRow = (row) => {
    const tipeRow = norm(row['Tipe']);
    if (tipeRow === 'location' || tipeRow === 'website') {
      // bukan file: jangan lewat Download Media / Send Media Kirimi, tempel sebagai teks
      isSendMedia = false;
      const url = String(row['URL'] || '').trim();
      const label = String(row['Caption'] || '').trim();
      if (url) {
        const line = label ? `${label} ${url}` : url;
        cleanOutput = cleanOutput.trim() ? `${cleanOutput}\n\n${line}` : line;
      }
      return;
    }
    mediaUrl = rapikanUrl(row['URL']);
    mediaCaption = String(row['Caption'] || '').trim() || 'Ini file yang diminta yaa.';
  };

  const exactRow = active.find(r => norm(r['Nama Link']) === mediaKey);
  if (exactRow && String(exactRow['URL'] || '').trim()) {
    resolveRow(exactRow);
  } else {
    const tokensOf = s => norm(s).split(/[^a-z0-9]+/i).filter(Boolean);
    const GENERIC = new Set(['foto','gambar','photo','video','klip','file','media','minta','contoh','link','dokumen']);
    const keyTokens = tokensOf(mediaKey);
    const qualifiers = keyTokens.filter(t => !GENERIC.has(t) && t.length >= 3);

    const rowBag  = (r) => [...tokensOf(r['Keyword']), ...tokensOf(r['Nama Link'])];
    const nameMatch    = (r) => { const nl = norm(r['Nama Link']); return !!nl && (nl.includes(mediaKey) || mediaKey.includes(nl)); };
    const keywordMatch = (r) => tokensOf(r['Keyword']).some(kw => keyTokens.includes(kw));

    let candidates = active.filter(r => nameMatch(r) || keywordMatch(r));
    // kandidat wajib memenuhi minimal satu kata pembeda yang diminta
    if (qualifiers.length) {
      candidates = candidates.filter(r => { const bag = rowBag(r); return qualifiers.some(q => bag.includes(q)); });
    }

    const byUrl = new Map();
    for (const r of candidates) {
      const u = String(r['URL'] || '').trim();
      if (!u || u.startsWith('<<')) continue;          // placeholder '<<ISI MANUAL>>' bukan URL
      if (!byUrl.has(u)) byUrl.set(u, r);
    }
    const unique = [...byUrl.values()];

    if (unique.length === 1) {
      resolveRow(unique[0]);
    } else if (unique.length > 1) {
      // sistem yang bertanya: media TIDAK dikirim, Steven TIDAK dinotif
      isMediaAmbiguous = true;
      isSendMedia = false;
      isMediaManual = false;
      mediaUrl = ''; mediaCaption = '';
      mediaCandidates = unique.map(r => ({ key: String(r['Nama Link'] || '').trim() }));
      const opts = mediaCandidates.map(c => c.key).filter(Boolean);
      const optText = opts.length === 2 ? `${opts[0]} atau ${opts[1]}`
                    : `${opts.slice(0, -1).join(', ')}, atau ${opts[opts.length - 1]}`;
      cleanOutput = `Ada beberapa yang cocok kak, mau yang mana yaa, ${optText}?`;
      console.log('SEND_MEDIA ambigu, tanya balik:', JSON.stringify(mediaCandidates));
    } else {
      console.warn('SEND_MEDIA key tidak ada di LINKS, fallback manual:', mediaKey);
      isSendMedia = false;
      isMediaManual = true;
      const userMsg = (preprocess && preprocess.actualUserMessage) || originalMessage || '';
      mediaRequestSummary = (mediaKey ? ('key="' + mediaKey + '" ') : '') + (userMsg ? ('| pesan user: ' + String(userMsg).slice(0, 300)) : '');
    }
  }
}

// ── MEDIA KE-2 (mis. foto + dokumen dalam satu balasan) ──
let isSendMedia2 = false, mediaUrl2 = '', mediaCaption2 = '';
if (isSendMedia && mediaUrl && !isMediaAmbiguous && mediaKeysAll.length >= 2) {
  let linkRows2 = [];
  try { linkRows2 = $('Rakit Konteks').first().json.katalog.links || []; } catch (e) {}
  const norm2 = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
  const active2 = linkRows2.filter(r => /^\s*(aktif|active|on|ya)\s*$/i.test(String(r['Status'] || '')));
  const key2 = mediaKeysAll.find(k => k && k !== mediaKey) || '';
  const row2 = key2 ? active2.find(r => norm2(r['Nama Link']) === key2) : null;
  if (row2) {
    const tipe2 = norm2(row2['Tipe']);
    const url2 = rapikanUrl(row2['URL']);
    if (url2 && !url2.startsWith('<<') && url2 !== mediaUrl && tipe2 !== 'location' && tipe2 !== 'website') {
      isSendMedia2 = true;
      mediaUrl2 = url2;
      mediaCaption2 = String(row2['Caption'] || '').trim() || 'Ini file berikutnya yaa.';
    }
  }
}

// ── FAIL LOUD: file diminta tapi tidak ada di katalog ──
// Notifikasi ke Steven saja tidak cukup. Selama balasannya masih berbunyi seperti
// janji, prospek menunggu sesuatu yang tidak pernah dikirim.
if (isMediaManual) {
  const low = cleanOutput.toLowerCase();
  const menjanjikan = /\b(kirim|kirimin|share|bagikan|lampirkan)\b/.test(low)
                   || /\b(ini|berikut)\s+(video|foto|file|dokumen|brosur|deck)/.test(low);
  if (menjanjikan) {
    const alt = linkAktifNama.length
      ? ' Yang sudah siap sekarang: ' + linkAktifNama.join(', ') + '.'
      : '';
    cleanOutput = 'Maaf kak, file itu belum ada di katalogku jadi belum bisa aku kirim '
                + 'langsung. Sudah aku teruskan ke Steven yaa, biar dia yang kirim.' + alt;
    console.warn('Balasan diganti: menjanjikan file yang tidak ada di LINKS. key=' + mediaKey);
  }
}

return [{
  json: {
    ...chatCounter, ...preprocess, ...item.json,
    cleanOutput,
    aiOutputRaw: aiOutput,
    isTalkToAdmin,
    isUnknown,
    needs_unknown: isUnknown ? 'true' : 'false',
    isSendMedia, mediaUrl, mediaCaption, mediaKey,
    isSendMedia2, mediaUrl2, mediaCaption2,
    isMediaManual, mediaRequestSummary,
    isMediaAmbiguous, mediaCandidates,
    isDeckRequest, deckRequest, deckRejected, deckMissing,
    original_message: originalMessage,
    is_new_user: isNewUser,
    nama_lengkap_merged: merged.nama_lengkap,
    nama_changed:        changed.nama_lengkap,
    nama_lengkap_changed: changed.nama_lengkap,
    nama_bisnis_merged:  merged.nama_bisnis,
    nama_bisnis_changed: changed.nama_bisnis,
    industri_merged:     merged.industri,
    industri_changed:    changed.industri,
    masalah_utama_merged:  merged.masalah_utama,
    masalah_utama_changed: changed.masalah_utama,
    volume_chat_merged:  merged.volume_chat,
    volume_chat_changed: changed.volume_chat,
    budget_range_merged:  merged.budget_range,
    budget_changed:       changed.budget_range,
    budget_range_changed: changed.budget_range,
    minat_paket_merged:  merged.minat_paket,
    minat_paket_changed: changed.minat_paket,
    bahasa_merged: bahasaMerged,
  }
}];

// FORMAT MEDIA NOTIF — notifikasi manual ke Steven.
// Dua jalur masuk ke sini: (1) key tidak ada di katalog LINKS, (2) key ada
// tapi unduhannya gagal / bukan file. Keduanya dibedakan di baris 'Sebab'
// supaya jelas yang perlu dibetulkan isi sheet-nya atau link-nya.
const pa = $('Process All').first().json;
const cc = $('Chat Counter').first().json;
const key = $('Resolve User Row').first().json.resolved_key || cc.user_wa || '';
const nama = cc.user_name || '';
const mediaKey = pa.mediaKey || '';
const summary = pa.mediaRequestSummary || '';
const urlKatalog = String(pa.mediaUrl || '').trim();
const sebab = urlKatalog
  ? ('file ADA di katalog tapi gagal diunduh -> ' + urlKatalog)
  : 'key tidak ada di katalog LINKS (atau statusnya belum Aktif)';

const message = `📸 [VIRA Steven] PERMINTAAN MEDIA - KIRIM MANUAL
User: ${key}
Nama: ${nama || '(belum ada nama)'}
Diminta: ${mediaKey || 'foto/video'}
Detail: ${summary || '(tidak ada detail)'}
Sebab: ${sebab}

User menunggu file dikirim. Balas langsung ke user yaa.
Chat: wa.me/${String(key).replace(/\D/g, '')}`;

const cfg = $('Parse Config').first().json.config;
let tujuan = [cfg.admin_phone].filter(Boolean);
if (!tujuan.length) { console.warn('admin_phone kosong — tidak ada tujuan notif media manual.'); return []; }

return tujuan.map(no => ({ json: { phone: String(no), message } }));

// COLLECT HANDOVER CONTEXT — STATS (fakta persisten) + MSG_BUFFER (transkrip sesi).
const digits = v => String(v ?? '').replace(/\D/g, '');
const key = $('Resolve User Row').first().json.resolved_key;

let statsRow = {};
try { statsRow = $('Read User STATS').all().map(i => i.json).find(r => digits(r['No WA']) === digits(key)) || {}; } catch (e) {}

let transcript = '';
try {
  const buf = $('Read MSG_BUFFER').all().map(i => i.json)
    .filter(r => digits(r['no_wa']) === digits(key))
    .sort((a, b) => Number(a.ts) - Number(b.ts));
  transcript = buf.map(r => `User: ${r.message}`).join('\n');
} catch (e) {}

const pa = $('Process All').first().json;
const profil = {
  // PRIORITAS: [FACTS] turn ini > nama_lengkap tersimpan > push name WA.
  // JANGAN pakai statsRow['Nama'] duluan — itu nama akun WhatsApp, bukan nama
  // yang user sebutkan sendiri.
  nama: pa.nama_lengkap_merged || statsRow['nama_lengkap'] || statsRow['Nama'] || $('Chat Counter').first().json.user_name || '',
  nama_akun_wa: statsRow['Nama'] || $('Chat Counter').first().json.user_name || '',
  no_wa: key,
  pesan_pertama: statsRow['Pesan Pertama'] || '',
  nama_bisnis: pa.nama_bisnis_merged || statsRow['nama_bisnis'] || '',
  industri: pa.industri_merged || statsRow['industri'] || '',
  masalah_utama: pa.masalah_utama_merged || statsRow['masalah_utama'] || '',
  volume_chat: pa.volume_chat_merged || statsRow['volume_chat'] || '',
  minat_paket: pa.minat_paket_merged || statsRow['minat_paket'] || '',
  budget_range: pa.budget_range_merged || statsRow['budget_range'] || '',
  brief_terisi: statsRow['brief_terisi'] || '(belum ada brief)',
  sudah_minta_deck: String(statsRow['deck_requested'] || '').trim().toUpperCase() === 'Y' ? 'ya' : 'belum',
  lead_source: $('Detect Lead Source').first().json.lead_source_final || statsRow['lead_source'] || '',
  jumlah_chat: statsRow['Counter'] || '',
};

return [{ json: {
  handover_profil: profil,
  handover_transcript: transcript || '(transkrip sesi tidak tersedia)',
  handover_trigger: 'DELEGATION'
}}];

parameters.text:
=Kamu asisten internal yang merangkum percakapan calon klien jasa AI Customer Service untuk Steven. Buat ringkasan SINGKAT, PADAT, FAKTUAL dalam Bahasa Indonesia. Hanya gunakan DATA PROFIL dan TRANSKRIP di bawah. JANGAN mengarang, tulis "belum diketahui" bila kosong. Tanpa basa-basi. Kalau "Nama akun WA" berbeda dari "Nama", pakai "Nama" dan sebutkan akun WA-nya dalam kurung. Kalau sama, sebut sekali saja.

ATURAN FORMAT (WAJIB): keluarkan PLAIN TEXT murni. DILARANG memakai markdown — tanpa tanda bintang (* atau **), tanpa underscore, tanpa backtick, tanpa heading (#), tanpa bullet simbol. Tulis label apa adanya, contoh: Profil Prospek: ...

Keluarkan PERSIS format berikut:
Profil Prospek: <nama, no WA, sumber>
Bisnisnya: <nama bisnis, industri, apa yang dijual>
Masalah Utama: <masalah yang dia keluhkan, atau belum dibahas>
Skala: <chat per hari, siapa yang balas sekarang>
Minat: <paket yang disebut, budget, deadline>
Status Brief: <isian brief yang sudah tertangkap, atau belum ada brief>
Poin Penting: <keberatan/kendala/urgensi, maks 3 poin>
Ringkasan: <1 kalimat konkret>

DATA PROFIL:
Nama: {{ $json.handover_profil.nama }}
Nama akun WA: {{ $json.handover_profil.nama_akun_wa }}
No WA: {{ $json.handover_profil.no_wa }}
Sumber: {{ $json.handover_profil.lead_source }}
Nama bisnis: {{ $json.handover_profil.nama_bisnis }}
Industri: {{ $json.handover_profil.industri }}
Masalah utama (sistem): {{ $json.handover_profil.masalah_utama }}
Volume chat (sistem): {{ $json.handover_profil.volume_chat }}
Minat paket (sistem): {{ $json.handover_profil.minat_paket }}
Budget (sistem): {{ $json.handover_profil.budget_range }}
Sudah minta deck: {{ $json.handover_profil.sudah_minta_deck }}
Brief terisi: {{ $json.handover_profil.brief_terisi }}
Jumlah chat: {{ $json.handover_profil.jumlah_chat }}

TRANSKRIP SESI:
{{ $json.handover_transcript }}

parameters.jsCode:
// FORMAT HANDOVER MESSAGE — bungkus ringkasan LLM (atau fallback deterministik).

// Sanitizer: buang sisa markdown dari output LLM. Prompt sudah minta plain text,
// tapi LLM masih sering bocor bold (**...** / *...*) — WA tidak butuh formatting,
// dan bintang yang tertinggal bikin pesan tim lapangan terlihat kotor.
// Underscore sengaja TIDAK dihapus: berisiko kena nama kolom (unit_interest, dll).
const stripMd = s => String(s || '')
  .replace(/\*/g, '')             // ** dan *
  .replace(/`/g, '')              // backtick
  .replace(/^#{1,6}\s*/gm, '')    // heading markdown
  .replace(/[ \t]+$/gm, '')       // trailing space
  .replace(/\n{3,}/g, '\n\n')     // rapikan blank line beruntun
  .trim();

let summary = '';
try { const s = $('Summarize Handover').first().json; summary = (s.content && s.content[0] && s.content[0].text) || s.text || ''; } catch (e) {}
summary = stripMd(summary);

const ctx = $('Collect Handover Context').first().json;
const p = ctx.handover_profil || {};
const trigger = ctx.handover_trigger || 'DELEGATION';

if (!summary || !summary.trim()) {
  summary = `PROSPEK: ${p.nama || '-'}, ${p.no_wa || '-'}, sumber ${p.lead_source || 'belum diketahui'}
BISNIS: ${p.nama_bisnis || 'belum diketahui'}${p.industri ? ' (' + p.industri + ')' : ''}
MASALAH UTAMA: ${p.masalah_utama || 'belum dibahas'}
SKALA: ${p.volume_chat || 'belum diketahui'} chat/hari
MINAT: ${p.minat_paket || 'belum disebut'}, budget ${p.budget_range || 'belum dibahas'}
BRIEF DECK: ${p.sudah_minta_deck === 'ya' ? 'sudah — ' + p.brief_terisi : 'belum'}`;
}

const header = {
  DELEGATION: '🤝 [VIRA Steven] PROSPEK MINTA DISAMBUNGKAN',
  HITL: '🙋 [VIRA Steven] AMBIL ALIH CHAT',
  CALL: '📞 [VIRA Steven] MINTA DITELEPON',
}[trigger] || '📋 [VIRA Steven] HANDOVER';

const message = `${header}

${summary}

— Chat: wa.me/${p.no_wa}`;

const cfg = $('Parse Config').first().json.config;
let tujuan = [cfg.admin_phone];
tujuan = (tujuan || []).filter(Boolean);
if (!tujuan.length) { console.warn('Tidak ada nomor tujuan handover (admin_phone kosong).'); return []; }

return tujuan.map(no => ({ json: { phone: String(no), message } }));

// ============================================================
// Send WA + Verify (Kirimi)
// Gabungan node lama: "Reply Chat Kirimi" (HTTP Request) + "Check API Response" (Code).
//
// KENAPA DIGABUNG:
// n8n me-retry MULAI DARI node yang gagal (runData node sebelumnya dipertahankan).
// Kalau validasi berdiri sendiri sebagai node terpisah, klik Retry hanya mengulang
// validasi dengan respons Kirimi yang lama -> throw lagi -> WA tidak pernah
// terkirim ulang. Dengan digabung, satu klik Retry benar-benar mengirim ulang.
//
// On Error = Stop Workflow (sengaja, jangan diubah): supaya execution jadi merah,
// Error Notifier jalan, dan execution bisa di-retry dari mobile dashboard.
//
// Retry HTTP ditangani DI DALAM kode ini (3x, jeda 5 detik) supaya persis meniru
// perilaku lama node "Reply Chat Kirimi" (retryOnFail: true, waitBetweenTries: 5000).
// Retry TIDAK berlaku untuk kegagalan "HTTP 200 tapi status:false" -- sama seperti
// node "Check API Response" lama yang tidak punya retryOnFail. Ini disengaja:
// respons status:false berarti Kirimi sudah memproses permintaan, jadi mengirim
// ulang otomatis berisiko pesan dobel. Kirim ulang untuk kasus itu = keputusan
// manusia, lewat tombol Retry.
// ============================================================

const KIRIMI_URL = 'https://api.kirimi.id/v1/send-message';
const TIMEOUT_MS = 60000;
const MAX_HTTP_ATTEMPTS = 3;
const WAIT_MS = 5000;

const sleep = (ms) => new Promise((resolve) => {
  if (typeof setTimeout === 'function') { setTimeout(resolve, ms); } else { resolve(); }
});

// --- kredensial: dari sheet CONFIG, sama persis dengan node HTTP lama ---
const _cfgAll = $('Parse Config').first().json.config || {};
const cfg = {
  user_code: _cfgAll.kirimi_user_code,
  secret: _cfgAll.kirimi_secret,
  device_id: _cfgAll.kirimi_device_id,
};

const phone = $('Chat Counter').first().json.user_wa;
const message = $('Process All').first().json.cleanOutput;

if (!phone) {
  throw new Error('Kirimi: nomor tujuan kosong (Chat Counter.user_wa)');
}
if (message === undefined || message === null || String(message).trim() === '') {
  throw new Error('Kirimi: pesan kosong (Process All.cleanOutput)');
}
if (!cfg.user_code || !cfg.secret || !cfg.device_id) {
  throw new Error('Kirimi: kredensial tidak lengkap (user_code/secret/device_id)');
}

// ---- 1) KIRIM (dengan retry khusus kegagalan HTTP) ----
let responseData = null;
let lastErr = null;

for (let attempt = 1; attempt <= MAX_HTTP_ATTEMPTS; attempt++) {
  try {
    responseData = await this.helpers.httpRequest({
      method: 'POST',
      url: KIRIMI_URL,
      body: {
        user_code: cfg.user_code,
        secret: cfg.secret,
        device_id: cfg.device_id,
        phone: phone,
        message: message,
      },
      json: true,
      timeout: TIMEOUT_MS,
    });
    lastErr = null;
    break;
  } catch (e) {
    lastErr = e;
    console.log('Kirimi HTTP gagal (percobaan ' + attempt + '/' + MAX_HTTP_ATTEMPTS + '): ' + (e && e.message ? e.message : String(e)));
    if (attempt < MAX_HTTP_ATTEMPTS) { await sleep(WAIT_MS); }
  }
}

if (lastErr) {
  throw new Error('Kirimi HTTP gagal setelah ' + MAX_HTTP_ATTEMPTS + ' percobaan: ' + (lastErr && lastErr.message ? lastErr.message : String(lastErr)));
}

// ---- 2) VERIFIKASI ISI RESPONS (logika lama "Check API Response") ----
const rd = (responseData && typeof responseData === 'object') ? responseData : {};
const explicitFail = rd.success === false || rd.status === false;
const isSuccess = !explicitFail && (
  rd.status === true ||
  rd.success === true ||
  (rd.data && rd.data.id) ||
  (rd.message && rd.message !== 'error')
);

if (!isSuccess) {
  throw new Error('Kirimi API gagal (HTTP 200 tapi respons menolak): ' + JSON.stringify(responseData));
}

console.log('Kirimi sukses:', JSON.stringify(responseData));
return [{ json: rd }];

const chatCounter = $('Chat Counter').first().json;

// DATA LANGSUNG DARI CHAT COUNTER NODE
const userNumber = chatCounter.user_wa;
const userName = chatCounter.user_name;
const userMessage = chatCounter.stats_message || chatCounter.original_message;   // [V2] '[gambar]' kalau kiriman tanpa teks

// VALIDASI SEDERHANA
if (!userNumber) {
  throw new Error("user_wa tidak ditemukan di input!");
}

console.log("✅ Data berhasil di-extract:");
console.log("- No WA:", userNumber);
console.log("- Nama:", userName);
console.log("- Pesan:", userMessage);

return [{
  json: {
    search_no_wa: userNumber,
    user_name: userName,
    user_message: userMessage,
    timestamp: chatCounter.formatted_date + ' ' + chatCounter.formatted_time + ' WIB',
    source: "chat_counter_node",
    is_valid: userNumber !== "unknown"
  }
}];

// ====================================================================
// PROCESS COUNTER & MERGE DATA — VIRA Steven
// Baris STATS lama diambil dari Resolve User Row (userRow), bukan dari
// pembacaan ulang seluruh tab. Node 'Read STATS' dibuang: barisnya sudah
// dibawa sejak awal giliran, dan satu-satunya penulis STATS di antara
// keduanya (Update Buffer) tidak menyentuh Counter.
// Dipertahankan dari V4: No WA primer / lid backup, 'Tanggal Chat Pertama'
// dibaca dari kolom yang benar, error -> stop (bukan menulis baris "ERROR").
// ====================================================================
try {
    const chatCounter = $('Chat Counter').first().json;
    const resolve = $('Resolve User Row').first().json;
    const resolvedKey = resolve.resolved_key;

    if (!resolvedKey) {
        console.warn('resolved_key kosong - skip update STATS');
        return [];
    }

    const digits = v => String(v ?? '').replace(/\D/g, '');
    const userName = chatCounter.user_name || 'User';
    const userMessage = chatCounter.stats_message || chatCounter.original_message || '';
    const lid = digits(chatCounter.user_lid);

    const row = resolve.userRow || {};
    const existingRow = Object.keys(row).length ? row : null;
    console.log('Baris STATS: ' + (existingRow ? 'SUDAH ADA' : 'USER BARU'));

    let counter, pesanPertama, tanggalPertama, intensitasChat;
    if (existingRow) {
        counter = parseInt(existingRow.Counter || existingRow.counter || 0) + 1;
        intensitasChat = parseInt(existingRow['Intensitas Chat'] || existingRow.intensitas_chat || 0) + 1;
        const pesanLama = existingRow['Pesan Pertama'] || existingRow.pesan_pertama;
        pesanPertama = (pesanLama && String(pesanLama).trim() !== '') ? pesanLama : userMessage;
        const tglLama = existingRow['Tanggal Chat Pertama'];
        tanggalPertama = (tglLama && String(tglLama).trim() !== '') ? tglLama : null;
    } else {
        counter = 1;
        intensitasChat = 1;
        pesanPertama = userMessage;
        tanggalPertama = null;
    }

    const hariIni = () => new Date().toLocaleDateString('en-GB', {
        timeZone: 'Asia/Jakarta', day: '2-digit', month: '2-digit', year: 'numeric'
    });
    if (!tanggalPertama) tanggalPertama = hariIni();

    return [{ json: {
        'No WA': resolvedKey,
        'lid': lid,
        'Tanggal': tanggalPertama,
        'TanggalSekarang': hariIni(),
        'Nama': userName,
        'Pesan Pertama': pesanPertama,
        'Counter': counter,
        'Intensitas Chat': intensitasChat
    }}];

} catch (error) {
    // jangan menulis baris "ERROR" ke sheet - cukup log & stop.
    console.error('Process Counter ERROR: ' + error.message);
    return [];
}

// ====================================================================
// UPDATE GREETING FLAG (V4 - disederhanakan)
// Dulu: pattern-matching teks balasan (rapuh, tergantung susunan
// kalimat). Sekarang: cukup dari flag is_new_user — kalau eksekusi
// ini mengirim intro ke user baru (reply sudah SUKSES terkirim
// karena node ini jalan setelah Reply Chat Kirimi), tandai Y.
// ====================================================================
const isNewUser = $('Cek_user_status').first().json.is_new_user === true;

if (isNewUser) {
  console.log('📝 [GREETING] intro terkirim ke user baru -> greeting_sent = Y');
}

return [{
  json: {
    update_needed: isNewUser ? 'true' : 'false',
    greeting_sent: 'Y'
  }
}];

// NODE: Siapkan Vision Request   [BARU - V2 VISION]
// ====================================================================
// Rakit body Anthropic Messages API untuk membaca gambar user.
// Semua gambar dalam satu window debounce dikirim dalam SATU request
// (lebih murah + model bisa membandingkan antar gambar).
// Sumber gambar = URL (source.type "url") -> Anthropic yang fetch.
//   Kalau URL Kirimi ternyata TIDAK publik, ganti blok image jadi base64:
//   { type:'image', source:{ type:'base64', media_type:'image/jpeg', data:<b64> } }
//   dan tambahkan node Download (HTTP Request, responseFormat=file) sebelum ini.
// ====================================================================
const base = $('Cek_user_status').first().json;
const cfg = (() => { try { return $('Parse Config').first().json.config || {}; } catch (e) { return {}; } })();

const imgs = Array.isArray(base.vision_images) ? base.vision_images : [];
const maxImg = Math.max(1, Number(cfg.vision_max_images ?? 3) || 3);
const picked = imgs.slice(-maxImg).filter(im => im && im.url);

if (!picked.length) {
  // Harusnya tidak terjadi (IF Ada Gambar sudah menyaring), tapi jangan
  // sampai node ini mengirim request kosong ke Anthropic.
  return [{ json: { vision_body: null, vision_image_count: 0, vision_skip: true } }];
}

const caption = String(base.user_message_final || '').trim();

const SYSTEM = [
  'Kamu asisten vision untuk Steven versi AI, chatbot WhatsApp yang menjual jasa AI Customer Service.',
  'Tugasmu HANYA mendeskripsikan gambar yang dikirim calon klien, supaya bot bisa membalas dengan tepat.',
  '',
  'ATURAN:',
  '- Bahasa Indonesia, padat, maksimal 5 kalimat per gambar.',
  '- Untuk tiap gambar tulis 2 baris:',
  '  KATEGORI: <pilih SATU> SCREENSHOT_CHAT | SCREENSHOT_SISTEM_ATAU_DASHBOARD | BROSUR_ATAU_IKLAN | LOGO_ATAU_BRANDING | FOTO_PRODUK_ATAU_TOKO | TANGKAPAN_LAYAR_PENAWARAN_ATAU_HARGA | KTP_ATAU_DOKUMEN_PRIBADI | BUKTI_TRANSFER | LAINNYA',
  '  ISI: apa yang terlihat.',
  '- Teks/angka penting di dalam gambar (nama bisnis, nominal, jumlah chat, tanggal, nama platform) tulis PERSIS apa adanya.',
  '- DILARANG menebak. Tidak terbaca -> tulis "tidak terbaca".',
  '- DILARANG menilai, menjawab pertanyaan user, atau memberi saran. Deskripsi saja.',
  '- PRIVASI: DILARANG menyalin NIK/nomor KTP, nomor rekening lengkap, NPWP, nomor kartu, atau data pelanggan pihak ketiga yang terlihat di screenshot. Sebut jenis dokumennya saja.',
  '- Lebih dari satu gambar -> beri nomor "Gambar 1", "Gambar 2", dst.'
].join('\n');

const content = picked.map(im => ({
  type: 'image',
  source: { type: 'url', url: String(im.url) }
}));

content.push({
  type: 'text',
  text: `Ada ${picked.length} gambar dari calon pembeli.` +
    (caption
      ? `\nPesan/caption yang user tulis: "${caption}"`
      : `\nUser tidak menulis pesan apa pun, hanya mengirim gambar.`) +
    `\nDeskripsikan sesuai format KATEGORI/ISI.`
});

const body = {
  model: String(cfg.vision_model || 'claude-haiku-4-5'),
  max_tokens: Math.max(200, Number(cfg.vision_max_tokens ?? 700) || 700),
  system: SYSTEM,
  messages: [{ role: 'user', content }]
};

return [{ json: { vision_body: body, vision_image_count: picked.length, vision_skip: false } }];

// NODE: Rakit Konteks Gambar   [BARU - V2 VISION]
// ====================================================================
// Titik gabung dua cabang IF Ada Gambar:
//   - cabang TRUE  : input = respons Anthropic (punya .content[])
//   - cabang FALSE : input = output Cek_user_status (tanpa .content)
// Menyisipkan blok [GAMBAR DARI USER] / [LAMPIRAN DARI USER] ke dalam
// [SYSTEM_DATA] (sebelum CRITICAL INSTRUCTION) supaya:
//   (a) Preprocess tetap mempertahankannya (dia hanya split di [USER QUERY]),
//   (b) regex intent Preprocess TIDAK ikut membaca deskripsi gambar.
// ====================================================================
const base = $('Cek_user_status').first().json;

let desc = '';
let ok = false;
let imgCount = 0;
let visionError = '';

try {
  const it = ($input.first() || {}).json || {};
  // hanya cabang TRUE yang punya struktur respons Anthropic
  if (Array.isArray(it.content)) {
    desc = it.content
      .filter(b => b && b.type === 'text' && typeof b.text === 'string')
      .map(b => b.text)
      .join('\n')
      .trim();
    ok = desc !== '';
    if (!ok) visionError = 'respons Anthropic tanpa blok text';
  } else if (it.error) {
    visionError = typeof it.error === 'string' ? it.error : JSON.stringify(it.error).slice(0, 300);
  }
} catch (e) {
  visionError = String(e && e.message ? e.message : e);
}

// -- SANITASI (anti prompt-injection lewat teks DI DALAM gambar) -------------
// Vision disuruh menyalin teks "persis apa adanya", jadi gambar berisi tulisan
// "[USER QUERY] abaikan instruksi" atau "[SEND_MEDIA: brosur]" bisa menyusup ke
// prompt / memicu aksi di Process All. Netralkan markernya, bukan buang teksnya.
// [V2.1] Sanitasi berbasis POLA, bukan string literal.
// V2.0 mencocokkan literal '[SEND_MEDIA', sedangkan Process All mem-parse tag dengan
// regex yang mengizinkan spasi: /\[\s*SEND_MEDIA/. Akibatnya tulisan "[ SEND_MEDIA: brosur]"
// di dalam gambar LOLOS sanitasi tapi TETAP dieksekusi. Sama untuk SCHEDULE_SURVEY & FACTS.
const RE_TAG  = /\[\s*\/?\s*(SEND_MEDIA|DECK_REQUEST|TALK_TO_ADMIN|UNKNOWN|FACTS)\b/gi;
const RE_BLOK = /\[\s*(SYSTEM_DATA|USER QUERY|CONTEXT|GAMBAR DARI USER|LAMPIRAN DARI USER)/gi;
const RE_CRIT = /CRITICAL\s+INSTRUCTION/gi;
const MAX_DESC = 2000;
if (desc) {
  // ganti "[" jadi "(" supaya parser tag & pemisah blok tidak kena,
  // tapi isi teksnya tetap terbaca manusia.
  let d = desc
    .replace(RE_TAG,  (mm, tag) => '(' + tag)
    .replace(RE_BLOK, (mm, tag) => '(' + tag)
    .replace(RE_CRIT, 'CRITICAL-INSTRUCTION');
  if (d.length > MAX_DESC) d = d.slice(0, MAX_DESC) + ' ...(dipotong)';
  if (d !== desc) console.warn('VISION: marker mencurigakan di deskripsi gambar - dinetralkan.');
  desc = d;
}

try { imgCount = Number($('Siapkan Vision Request').first().json.vision_image_count) || 0; } catch (e) { }
if (!imgCount) imgCount = Array.isArray(base.vision_images) ? base.vision_images.length : 0;

if (visionError) console.warn('VISION gagal:', visionError);

// [V2.1] blok mengikuti vision_mode. Di V2.0, mode mati tetap menghasilkan blok
// "sistem GAGAL membaca" -> terbaca klien sebagai fitur RUSAK, bukan fitur di luar paket.
const visionMode = (() => {
  try { return String($('Parse Config').first().json.config.vision_mode || 'full').toLowerCase(); }
  catch (e) { return 'full'; }
})();

let blok = '';
if (visionMode === 'off') {
  // perilaku V1.3: lampiran diabaikan sepenuhnya, tidak ada blok yang disisipkan.
  blok = '';
} else if (base.has_image && visionMode === 'full') {
  blok = ok
    ? `[GAMBAR DARI USER]\nUser baru saja mengirim ${imgCount} gambar. Hasil pembacaan gambar (sumber tepercaya, boleh kamu rujuk):\n${desc}\nTanggapi isi gambarnya. DILARANG bilang kamu tidak bisa melihat gambar.`
    : `[GAMBAR DARI USER]\nUser mengirim gambar tapi sistem GAGAL membacanya. Minta maaf singkat lalu minta user menuliskan inti isi gambarnya. DILARANG menebak isinya.`;
  if (Number(base.vision_images_dropped) > 0) {
    blok += `\nCatatan: user mengirim lebih banyak gambar, hanya ${imgCount} terakhir yang terbaca. Kalau relevan, minta user mengirim ulang yang belum terbahas.`;
  }
} else if (base.has_image || Number(base.other_media_count) > 0) {
  // mode 'ack' (gambar maupun bukan), ATAU media non-gambar di mode 'full'.
  const jenis = base.has_image
    ? (Number(base.other_media_count) > 0 ? 'gambar dan lampiran lain' : 'gambar')
    : 'lampiran non-gambar (video/pesan suara/dokumen/lokasi/stiker)';
  blok = `[LAMPIRAN DARI USER]\nUser mengirim ${jenis} yang BELUM bisa kamu buka. Akui dengan sopan dan ramah bahwa kirimannya sudah masuk, lalu minta intinya diketik singkat, atau tawarkan disambungkan ke tim. DILARANG menebak isinya. DILARANG bilang "sistem gagal membaca" atau menyalahkan sistem.`;
}

let ai = String(base.ai_input_text || '');
if (blok) {
  if (ai.includes('CRITICAL INSTRUCTION')) {
    ai = ai.replace('CRITICAL INSTRUCTION', blok + '\n\nCRITICAL INSTRUCTION');
  } else if (ai.includes('[USER QUERY]')) {
    ai = ai.replace('[USER QUERY]', blok + '\n\n[USER QUERY]');
  } else {
    ai = blok + '\n\n' + ai;
  }
}

return [{
  json: {
    ...base,
    ai_input_text: ai,
    image_desc: desc,
    vision_ok: ok,
    vision_error: visionError,
    vision_image_count: imgCount
  }
}];

// Rakit Konteks — VIRA Steven
// Membangun 5 blok data yang disisipkan ke system prompt.
// Aturan penting: kolom "Catatan Internal" (PROGRAM & LINKS) dan baris
// "Boleh Dibagikan = Tidak" (ABOUT_STEVEN) TIDAK BOLEH dikirim sebagai fakta.
const item = $input.first().json;
const cfg  = $('Parse Config').first().json.config || {};

// Baris sheet datang dari katalog cache (lihat node 'Muat Katalog'), bukan dari
// $('Read ...') langsung — saat cache HIT node Sheets-nya memang tidak dijalankan.
const KATALOG = item.katalog || { faq: [], program: [], links: [], about: [] };
const rows = (kunci) => (Array.isArray(KATALOG[kunci]) ? KATALOG[kunci] : []);
const txt = (v) => String(v ?? '').trim();
const aktif = (v) => /^(aktif|active|on|ya|yes)$/i.test(txt(v));

// ---------- 1. prospect_context ----------
let stats = {};
try { stats = $('Resolve User Row').first().json.userRow || $('Resolve User Row').first().json || {}; }
catch (e) { stats = {}; }

const TTL_HARI = parseInt(cfg.fact_ttl_days || '60', 10);
const sekarang = Math.floor(Date.now() / 1000);
const masihSegar = (ts) => {
  const t = parseInt(ts || '0', 10);
  if (!t) return true;                    // tidak ada stempel waktu -> anggap masih berlaku
  return (sekarang - t) < TTL_HARI * 86400;
};

const FAKTA = ['nama_lengkap', 'nama_bisnis', 'industri', 'masalah_utama',
               'volume_chat', 'budget_range', 'minat_paket'];
const barisProspek = [];
for (const f of FAKTA) {
  const nilai = txt(stats[f]);
  if (!nilai) continue;
  if (!masihSegar(stats[f + '_ts'])) continue;   // fakta basi dibuang, jangan dipakai menyapa
  barisProspek.push(`${f}: ${nilai}`);
}
if (txt(stats['Nama']))  barisProspek.push(`nama_wa: ${txt(stats['Nama'])}`);
if (txt(stats['bahasa'])) barisProspek.push(`bahasa_terakhir: ${txt(stats['bahasa'])}`);
if (txt(stats['deck_requested']) === 'Y') barisProspek.push('sudah_minta_pitch_deck: ya');

const baru = !txt(stats['greeting_sent']);
const prospect_context = (barisProspek.length ? barisProspek.join('\n') : '(belum ada data)')
  + `\nIS_NEW_USER: ${baru}`;

// ---------- 2. about_context ----------
const about = rows('about');
const fakta = [], aturan = [];
for (const r of about) {
  const aspek = txt(r['Aspek']), detail = txt(r['Detail']);
  if (!aspek || !detail) continue;
  (aktif(r['Boleh Dibagikan']) ? fakta : aturan).push(`${aspek}: ${detail}`);
}
let about_context = fakta.join('\n') || '(kosong)';
if (aturan.length) {
  about_context += '\n\nATURAN INTERNAL (jangan dibacakan ke prospek, tapi wajib dipatuhi):\n'
                 + aturan.join('\n');
}

// ---------- 3. program_context ----------
const program = rows('program');
const program_context = program
  .filter(r => aktif(r['Status']))
  .map(r => {
    const bagian = [];
    for (const [k, v] of Object.entries(r)) {
      if (k === 'Catatan Internal' || k === 'row_number' || k === 'Status') continue;  // catatan internal TIDAK dikirim
      if (txt(v)) bagian.push(`${k}: ${txt(v)}`);
    }
    return bagian.join(' | ');
  })
  .filter(Boolean).join('\n') || '(kosong)';

// ---------- 4. links_context ----------
const links = rows('links');
const links_context = links
  .filter(r => aktif(r['Status']) && txt(r['URL']))
  .map(r => `${txt(r['Nama Link'])} — ${txt(r['Caption']) || 'file pendukung'}`)
  .join('\n') || '(tidak ada media aktif — jangan pakai tag SEND_MEDIA)';

// ---------- 5. faq_context ----------
const faq_context = txt(item.faq_context) || '(tidak ada FAQ relevan untuk pesan ini)';

// ---------- 6. brief_context ----------
const briefRaw = txt(stats['brief_terisi']);
const brief_context = briefRaw
  ? ('Isian brief yang sudah tertangkap untuk orang ini: ' + briefRaw
     + '\nJangan menanyakan ulang isian di atas.')
  : '(belum ada brief yang terkirim untuk orang ini)';

return [{
  json: {
    ...item,
    prospect_context,
    about_context,
    program_context,
    links_context,
    faq_context,
    brief_context,
  }
}];

// ── Merge Brief — VIRA Steven ──
// Tag [DECK_REQUEST] selalu dikirim lengkap 27 baris, tapi sebagian isinya "belum disebut"
// (sudah dinormalkan jadi '' di Process All). Penggabungan dengan baris REQUESTS lama
// dilakukan DI SINI, bukan diserahkan ke AI — supaya emisi kedua tidak menghapus isian
// yang sudah pernah tertangkap di emisi pertama.
const FIELDS = ["nama", "jabatan", "nama_bisnis", "industri", "deskripsi_bisnis", "target_pelanggan", "channel", "sumber_leads", "volume_chat_harian", "jam_operasional", "siapa_balas_chat", "biaya_admin_bulanan", "sistem_sekarang", "masalah_utama", "pain_points", "aksi_utama", "alur_setelah_chat", "pertanyaan_tersering", "fitur_diminati", "nilai_transaksi", "prospek_per_bulan", "minat_paket", "budget_range", "deadline", "urgensi", "bahasa_deck", "catatan"];
const LABEL = {"nama": "Nama", "jabatan": "Jabatan", "nama_bisnis": "Bisnis", "industri": "Industri", "deskripsi_bisnis": "Deskripsi", "target_pelanggan": "Target pelanggan", "channel": "Channel", "sumber_leads": "Sumber leads", "volume_chat_harian": "Chat/hari", "jam_operasional": "Jam operasional", "siapa_balas_chat": "Yang balas chat", "biaya_admin_bulanan": "Biaya admin", "sistem_sekarang": "Sistem sekarang", "masalah_utama": "Masalah utama", "pain_points": "Keluhan lain", "aksi_utama": "Aksi utama", "alur_setelah_chat": "Alur setelah chat", "pertanyaan_tersering": "Pertanyaan tersering", "fitur_diminati": "Fitur diminati", "nilai_transaksi": "Nilai transaksi", "prospek_per_bulan": "Prospek/bulan", "minat_paket": "Minat paket", "budget_range": "Budget", "deadline": "Deadline", "urgensi": "Urgensi", "bahasa_deck": "Bahasa", "catatan": "Catatan"};

const pa  = $('Process All').first().json;
const key = $('Resolve User Row').first().json.resolved_key;
const digits = v => String(v ?? '').replace(/\D/g, '');

let lama = {};
try {
  const baris = $('Read REQUESTS').all().map(i => i.json)
    .filter(r => r && digits(r['no_wa']) === digits(key));
  lama = baris.length ? baris[baris.length - 1] : {};
} catch (e) { console.warn('Read REQUESTS tidak terbaca:', e.message); }

const baru = pa.deckRequest || {};
const hasil = {};
for (const f of FIELDS) {
  const v = String(baru[f] ?? '').trim();
  const l = String(lama[f] ?? '').trim();
  hasil[f] = v || l;                       // nilai baru menang hanya kalau ada isinya
}

const terisi = FIELDS.filter(f => hasil[f]);
const kosong = FIELDS.filter(f => !hasil[f]);
const nowS = Math.floor(Date.now() / 1000);
const stamp = new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' });
const tsLama = String(lama['ts'] || '').trim();
const revisi = tsLama ? ' (diperbarui)' : '';

const notif_text =
  `📋 [VIRA Steven] BRIEF DECK${revisi}\n` +
  `${hasil.nama_bisnis || '(nama bisnis belum disebut)'} — ${hasil.industri || '-'}\n` +
  `WA: ${key}\n` +
  `Kelengkapan: ${terisi.length}/${FIELDS.length}\n\n` +
  terisi.map(f => `${LABEL[f] || f}: ${hasil[f]}`).join('\n') +
  `\n\nBelum tergali: ${kosong.map(f => LABEL[f] || f).join(', ') || '(lengkap)'}`;

return [{
  json: {
    ...hasil,
    ts: tsLama || stamp,
    update_terakhir: stamp,
    no_wa: key,
    kelengkapan: `${terisi.length}/${FIELDS.length}`,
    status_followup: String(lama['status_followup'] || '').trim() || 'BARU',
    brief_terisi: terisi.join(','),
    brief_jumlah: terisi.length,
    notif_text,
  }
}];

// Guard: pastikan yang terunduh benar-benar file, bukan halaman HTML.
// Drive/Dropbox membalas HTTP 200 + HTML (konfirmasi virus-scan, halaman login) kalau
// link-nya tidak benar-benar direct. responseFormat "file" menelannya sebagai biner
// tanpa error, lalu Kirimi mengirim file rusak — gagal diam-diam.
const it = $input.first();
const bin = (it && it.binary && it.binary.data) ? it.binary.data : null;
const mime = String((bin && bin.mimeType) || '').toLowerCase();
const rusak = !bin || mime.startsWith('text/html') || mime.includes('xhtml');
if (rusak) {
  console.warn('Download media gagal / bukan file. mime=' + (mime || '(tidak ada biner)'));
}
return [{ json: { ...(it.json || {}), file_ok: !rusak, file_mime: mime }, binary: it.binary }];

